function countWays(n: number): number {
  const memo = new Map<number, number>();
  const ways = (i: number): number => {
    if (i <= 1) return 1;
    if (memo.has(i)) return memo.get(i)!;
    const v = ways(i - 1) + ways(i - 2);
    memo.set(i, v);
    return v;
  };
  return ways(n);
}

