function countWays(n: number): number {
  const ways = new Array<number>(n + 1).fill(0);
  ways[0] = 1;
  ways[1] = 1;
  for (let i = 2; i <= n; i++) ways[i] = ways[i - 1] + ways[i - 2];
  return ways[n];
}

